        }
        else{
            build(left(p),L,(L+R)/2);
            build(right(p),(L+R)/2+1,R);
            int l=st[left(p)];
            int r=st[right(p)];
            st[p]=l+r;
        }
    }
    int rmq(int p,int L,int R,int i,int j){
        if(i&gt;R||j&lt;L)
            return -1;
        propagate(p,L,R);
        if(i&lt;=L&&R&lt;=j){
            return st[p];
        }
        int l=rmq(left(p),L,(L+R)/2,i,j);
        int r=rmq(right(p),(L+R)/2+1,R,i,j);
        if(l==-1)return r;
        if(r==-1)return l;
        return l+r;
    }
    int flip(int sign){
        if(sign==SET)
            return CLEAR;
        if(sign==CLEAR)
            return SET;
        if(sign==FLIP)
            return 0;
        if(sign==0)
            return FLIP;
    }
    void propagate(int p,int L,int R){
        if(U[p]==SET){
            st[p]=R-L+1;
            if(L!=R){
                U[left(p)]=SET;
                U[right(p)]=SET;
            }
        }
        else if(U[p]==CLEAR){
            st[p]=0;
            if(L!=R){
                U[left(p)]=CLEAR;
                U[right(p)]=CLEAR;
            }
        }
        else if(U[p]==FLIP){
            st[p]=R-L+1-st[p];
            if(L!=R){
                U[left(p)]=flip(U[left(p)]);
                U[right(p)]=flip(U[right(p)]);
            }
        }

        U[p]=0;
    }
public:
    void rangeSet(int p,int L,int R,int i,int j){
        propagate(p,L,R);
        if(R&lt;i||L&gt;j)
            return;
        if(L==R){
            st[p]=1;
            return;
        }
        if(i&lt;=L&&R&lt;=j){
            st[p]=R-L+1;
            U[left(p)]=SET;
            U[right(p)]=SET;
            return;
        }
        rangeSet(left(p),L,(L+R)/2,i,j);
        rangeSet(right(p),(L+R)/2+1,R,i,j);
        st[p]=st[left(p)]+st[right(p)];
    }
    void rangeClear(int p,int L,int R,int i,int j){
        propagate(p,L,R);
        if(R&lt;i||L&gt;j)
            return;
        if(L==R){
            st[p]=0;
            U[p]=0;
            return;
        }
        if(i&lt;=L&&R&lt;=j){
            st[p]=0;
            U[left(p)]=CLEAR;
            U[right(p)]=CLEAR;
            return;
        }
        rangeClear(left(p),L,(L+R)/2,i,j);
        rangeClear(right(p),(L+R)/2+1,R,i,j);
        st[p]=st[left(p)]+st[right(p)];
    }
    void rangeFlip(int p,int L,int R,int i,int j){
        propagate(p,L,R);
        if(R&lt;i||L&gt;j)
            return;
        if(L==R){
            st[p]=(st[p]==1)?0:1;
            return;
        }
        if(i&lt;=L&&R&lt;=j){
            st[p]=R-L+1-st[p];
            U[left(p)]=flip(U[left(p)]);
            U[right(p)]=flip(U[right(p)]);
            return;
        }
        rangeFlip(left(p),L,(L+R)/2,i,j);
        rangeFlip(right(p),(L+R)/2+1,R,i,j);
        st[p]=st[left(p)]+st[right(p)];
    }

    void buildTree(){
        build(1,0,N-1);
    }
    int query(int left,int right){
        return rmq(1,0,N-1,left,right); 
    }
};
